"""Recursive CTEs in SQLite: series, hierarchies, bill of materials, graphs and calendar gaps.

A recursive CTE has an anchor query (the starting rows) and a recursive query that reads the rows
produced in the previous round. It stops when a round produces no new rows. Each function below
returns plain Python data so the results can be checked against ordinary recursion.
"""

import sqlite3


def series(conn: sqlite3.Connection, n: int) -> list[int]:
    """1..n generated by the database itself."""
    sql = """
    WITH RECURSIVE s(x) AS (
        SELECT 1
        UNION ALL
        SELECT x + 1 FROM s WHERE x < ?
    )
    SELECT x FROM s
    """
    return [r[0] for r in conn.execute(sql, (n,))]


def reporting_chain(conn: sqlite3.Connection) -> list[tuple[int, str, int, str]]:
    """Every employee with their depth in the tree and the path from the top (table: emp)."""
    sql = """
    WITH RECURSIVE tree(id, name, depth, path) AS (
        SELECT id, name, 0, name FROM emp WHERE manager_id IS NULL
        UNION ALL
        SELECT e.id, e.name, t.depth + 1, t.path || ' > ' || e.name
        FROM emp e JOIN tree t ON e.manager_id = t.id
    )
    SELECT id, name, depth, path FROM tree ORDER BY path
    """
    return [(r[0], r[1], r[2], r[3]) for r in conn.execute(sql)]


def parts_explosion(conn: sqlite3.Connection, assembly: str) -> dict[str, int]:
    """Total quantity of each *base* part (one with no children) needed to build ``assembly``.

    Table bom(parent, child, qty). Quantities multiply down the tree: 2 wheels x 36 spokes = 72.
    """
    sql = """
    WITH RECURSIVE need(part, qty) AS (
        SELECT ?, 1
        UNION ALL
        SELECT b.child, n.qty * b.qty FROM need n JOIN bom b ON b.parent = n.part
    )
    SELECT part, SUM(qty) FROM need
    WHERE part NOT IN (SELECT parent FROM bom)
    GROUP BY part ORDER BY part
    """
    return {part: total for part, total in conn.execute(sql, (assembly,))}


def reachable(conn: sqlite3.Connection, start: int) -> list[int]:
    """Nodes reachable from ``start`` in a directed graph (table edge(src, dst)), cycles allowed.

    UNION (not UNION ALL) discards a row already seen, so a cycle cannot make the query run forever.
    """
    sql = """
    WITH RECURSIVE seen(node) AS (
        SELECT ?
        UNION
        SELECT e.dst FROM edge e JOIN seen s ON e.src = s.node
    )
    SELECT node FROM seen ORDER BY node
    """
    return [r[0] for r in conn.execute(sql, (start,))]


def walks_without_guard(conn: sqlite3.Connection, start: int, max_depth: int) -> int:
    """Rows produced by UNION ALL with only a depth limit: on a cycle the same nodes keep returning.

    Shows why the guard matters: the row count grows with the depth limit instead of stopping.
    """
    sql = """
    WITH RECURSIVE walk(node, depth) AS (
        SELECT ?, 0
        UNION ALL
        SELECT e.dst, w.depth + 1 FROM edge e JOIN walk w ON e.src = w.node WHERE w.depth < ?
    )
    SELECT COUNT(*) FROM walk
    """
    return int(conn.execute(sql, (start, max_depth)).fetchone()[0])


def daily_totals_with_gaps_filled(conn: sqlite3.Connection) -> list[tuple[str, float]]:
    """Sales per day from table sales(day, amount), with 0 for days that had no sales."""
    sql = """
    WITH RECURSIVE days(day) AS (
        SELECT MIN(day) FROM sales
        UNION ALL
        SELECT date(day, '+1 day') FROM days WHERE day < (SELECT MAX(day) FROM sales)
    )
    SELECT d.day, COALESCE(SUM(s.amount), 0.0)
    FROM days d LEFT JOIN sales s ON s.day = d.day
    GROUP BY d.day ORDER BY d.day
    """
    return [(r[0], r[1]) for r in conn.execute(sql)]


def demo_database() -> sqlite3.Connection:
    conn = sqlite3.connect(":memory:")
    conn.executescript(
        """
        CREATE TABLE emp (id INTEGER PRIMARY KEY, name TEXT, manager_id INTEGER);
        INSERT INTO emp VALUES (1,'Ada',NULL),(2,'Ben',1),(3,'Cy',1),(4,'Di',2),(5,'Eli',2),(6,'Flo',4);

        CREATE TABLE bom (parent TEXT, child TEXT, qty INTEGER);
        INSERT INTO bom VALUES ('bike','frame',1),('bike','wheel',2),('wheel','spoke',36),
                               ('wheel','rim',1),('frame','tube',3),('frame','bolt',8),('wheel','bolt',4);

        CREATE TABLE edge (src INTEGER, dst INTEGER);
        INSERT INTO edge VALUES (1,2),(2,3),(3,1),(3,4),(5,6);

        CREATE TABLE sales (day TEXT, amount REAL);
        INSERT INTO sales VALUES ('2026-01-01',10),('2026-01-01',5),('2026-01-04',7.5),('2026-01-06',2);
        """
    )
    return conn


if __name__ == "__main__":
    db = demo_database()
    print("series(5):", series(db, 5))
    for _id, _name, depth, path in reporting_chain(db):
        print("  " * depth + path.split(" > ")[-1], f"(depth {depth})")
    print("bike needs:", parts_explosion(db, "bike"))
    print("reachable from 1:", reachable(db, 1))
    print("UNION ALL rows at depth 5 / 10 / 20:", [walks_without_guard(db, 1, d) for d in (5, 10, 20)])
    print("daily totals:", daily_totals_with_gaps_filled(db))
